    // index
    "ix.0": "ہائی اسکول · 1877 سے امریکی تاریخ · §113.41 · مسئلہ پر مبنی تعلّم",
    "ix.1": "برمنگھم، 1963 — شہری حقوق کی تحریک",
    "ix.2": "ایک مسئلہ پر مبنی تعلّمی یونٹ۔ طلبہ 1963 کے موسمِ بہار میں برمنگھم میں قدم رکھتے ہیں، کسی اسٹیک ہولڈر کا نقطۂ نظر اختیار کرتے ہیں، اور غیر منصفانہ قانون، عدم تشدد اور تبدیلی کے بارے میں ایک حقیقی، غیر منظم سوال پر کام کرتے ہیں — سطحی سے گہرے اور گہرے سے منتقلی تک تعمیر کرتے ہوئے۔ استاد ایک رہنما ہے، جوابی کلید نہیں۔",
    "ix.3": "<b>محرک سوال:</b> یہ برمنگھم میں 1963 کا موسمِ بہار ہے۔ جب قانون بذاتِ خود غیر منصفانہ ہو، تو تحریک کو تبدیلی کے لیے کیسے دباؤ ڈالنا چاہیے — اور طلبہ، رہنماؤں اور عہدیداروں کو کیسے ردِعمل دینا چاہیے؟",
    "ix.4": "تین مرحلوں کا راستہ (انہیں ترتیب سے کریں)",
    "ix.5": "مسئلہ حل کرنا ایک <b>منتقلی</b> اقدام ہے — یہ تبھی کام کرتا ہے جب طلبہ کے پاس استدلال کرنے کے لیے علم ہو۔ اسی لیے مرحلہ 3 کا مسئلہ جان بوجھ کر مرحلہ 1 اور 2 کے پیچھے <b>مقفل</b> رکھا گیا ہے۔",
    "ix.6": "علم کی تعمیر کریں",
    "ix.7": "الفاظ، علیحدگی اور تحریک کے بارے میں اہم حقائق، ایک جِگسا مطالعہ، اور برمنگھم تک کے راستے کی ایک ٹائم لائن۔ ~1–2 پیریڈ۔",
    "ix.8": "جوڑیں اور منظّم کریں",
    "ix.9": "حکمتِ عملی–نتائج کا تصوراتی نقشہ، بنیادی ماخذ، متحارب نقطہ ہائے نظر، اور ایک منظّم دلیل۔ ~1–2 پیریڈ۔",
    "ix.10": "مسئلہ حل کریں",
    "ix.11": "مسئلے سے ملیں، اسٹیک ہولڈر کا کردار اختیار کریں، تحقیق کریں، عمل کا ایک لائحہ تجویز کریں اور اس کا دفاع کریں، جائزہ لیں۔ ~2–4 پیریڈ۔",
    "ix.12": "⛔ <b>دروازہ:</b> مرحلہ 3 کا مسئلہ اُس وقت تک نہ کھولیں جب تک طلبہ سطحی اور گہری سرگرمیاں مکمل نہ کر لیں۔ مسئلے سے بہت جلد ملنا تحقیق کو اندازہ لگانے میں بدل دیتا ہے۔",
    "ix.13": "بڑا خیال اور مقاصد",
    "ix.14": "<b>بڑا خیال:</b> جب لوگ یہ نتیجہ اخذ کرتے ہیں کہ قانون بذاتِ خود غیر منصفانہ ہے، تو انہیں تبدیلی کے لیے دباؤ ڈالنے کا طریقہ طے کرتے وقت <b>حکمتِ عملی، خطرے اور ضمیر</b> کو تولنا پڑتا ہے — اور 1963 میں برمنگھم میں کیے گئے فیصلوں نے ایک قوم کو ہلا دیا اور 1964 کے شہری حقوق ایکٹ اور 1965 کے ووٹنگ رائٹس ایکٹ کو تشکیل دیا۔",
    "ix.15": "<b>جانیں:</b> شہری حقوق کی تحریک کا ارتقا — Brown v. Board، مانٹگمری بس بائیکاٹ، دھرنے اور SNCC، برمنگھم مہم اور بچوں کی صلیبی مہم، واشنگٹن پر مارچ، اور اُن سے نتیجہ خیز تاریخی قوانین۔",
    "ix.16": "<b>سمجھیں:</b> 1963 کا وہی موسمِ بہار ہر اسٹیک ہولڈر کے نقطۂ نظر سے — رہنما، طالب علم، اعتدال پسند، عہدیدار اور وفاقی حکومت سب کی نظر سے — گہرائی سے مختلف نظر آتا ہے۔",
    "ix.17": "<b>کریں:</b> مسئلہ حل کرنے اور فیصلہ سازی کے عمل کو شروع سے آخر تک چلائیں — مسئلے کی نشاندہی کریں، معلومات جمع کریں، اختیارات کی فہرست بنائیں اور تولیں، عمل کا ایک لائحہ منتخب کریں اور اس کا دفاع کریں، اور اس کا جائزہ لیں (§113.41(c)(31)(B))۔",
    "ix.18": "وہ معیارات جن کے ساتھ یہ یونٹ ہم آہنگ ہے (§113.41)",
    "ix.19": "TEKS SE",
    "ix.20": "یہ یونٹ میں کہاں ہے",
    "ix.21": "شہری حقوق کی تحریک کا اثر — اس کا ارتقا، کلیدی واقعات، رہنما، اور دستاویزات — سطحی میں حقائق، گہرے میں ماخذ",
    "ix.22": "معلومات کا تجزیہ اور جائزہ لیں؛ ماخذ میں نقطۂ نظر اور تعصب کی نشاندہی کریں — گہرے میں تجزیہ، منتقلی میں تحقیق",
    "ix.23": "نتائج کو تحریری اور زبانی صورت میں پہنچائیں — گہرے میں دلیل، منتقلی میں خلاصہ",
