    "as.8a": "<b>مسئلہ متعین</b>", "as.8": "کسی اسٹیک ہولڈر کے نقطۂ نظر سے حقیقی مسئلے اور یہ کس کو متاثر کرتا ہے، کا نام بتاتا ہے۔", "as.8b": "مسئلے کو ڈھونڈے بغیر کہانی دہراتا ہے۔",
    "as.9a": "<b>اختیارات تولے گئے</b>", "as.9": "فوائد اور نقصانات کے ساتھ ایک سے زیادہ اختیار پر غور کرتا ہے۔", "as.9b": "ایک جواب پر کود جاتا ہے؛ کوئی متبادل نہیں۔",
    "as.10a": "<b>شواہد اور تحقیق</b>", "as.10": "ایک سے زیادہ ماخذ سے حقائق استعمال کرتا ہے؛ اعتباریت پر سوال کرتا ہے۔", "as.10b": "تھوڑے شواہد، یا صرف ایک ماخذ۔",
    "as.11a": "<b>حل اور استدلال</b>", "as.11": "عمل کا ایک لائحہ تجویز کرتا ہے اور استدلال بیان کرتا ہے؛ ایک سے زیادہ درست راہ کے لیے کھلا۔", "as.11b": "حل بغیر وجوہات کے بیان کیا گیا۔",
    "as.12a": "<b>تناظر</b>", "as.12": "ایک سے زیادہ اسٹیک ہولڈر کے نقطۂ نظر سے مسئلے کو دکھاتا ہے۔", "as.12b": "صرف ایک ہی نقطۂ نظر۔",
    "as.13a": "<b>ترسیل</b>", "as.13": "واضح، منظّم، اور تمام 8 حصوں کا احاطہ کرتا ہے۔", "as.13b": "غیر منظّم یا حصے غائب۔",
    "as.14a": "<b>تشخیص</b>", "as.14": "بیان کرتا ہے کہ وہ کیسے جانیں گے کہ لائحۂ عمل کام کر گیا۔", "as.14b": "حل جانچنے کا کوئی طریقہ نہیں۔",
